import{_ as e,o,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Keeping Ceph RGW Object Storage Consistent - Jane Zhu, Bloomberg","description":"","frontmatter":{"title":"Keeping Ceph RGW Object Storage Consistent - Jane Zhu, Bloomberg","date":"2025-01-26T00:00:00.000Z","updated":"2025-01-26T00:00:00.000Z","tags":["Ceph","RGW","数据一致性","分布式存储","存储集群"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keeping_Ceph_RGW_Object_Storage_Consistent_-_Jane_Zhu_Bloomberg.md","filePath":"posts/2025/Keeping_Ceph_RGW_Object_Storage_Consistent_-_Jane_Zhu_Bloomberg.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Keeping_Ceph_RGW_Object_Storage_Consistent_-_Jane_Zhu_Bloomberg.md"};function a(l,t,i,g,_,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要-ceph-rgw-数据一致性问题及解决方案讨论" tabindex="-1">会议纪要：Ceph RGW 数据一致性问题及解决方案讨论 <a class="header-anchor" href="#会议纪要-ceph-rgw-数据一致性问题及解决方案讨论" aria-label="Permalink to &quot;会议纪要：Ceph RGW 数据一致性问题及解决方案讨论&quot;">​</a></h3><p><strong>会议主题</strong>: 保持 Ceph RGW 对象存储数据一致性</p><p><strong>主讲人</strong>: Jane Zhu，Bloomberg 存储工程团队高级软件工程师</p><p><strong>会议时间</strong>: 未知</p><h4 id="_1-会议背景与目标" tabindex="-1">1. <strong>会议背景与目标</strong> <a class="header-anchor" href="#_1-会议背景与目标" aria-label="Permalink to &quot;1. **会议背景与目标**&quot;">​</a></h4><ul><li><strong>Bloomberg 简介</strong>: Bloomberg 是一家全球领先的金融科技公司，提供数据服务、新闻分析和软件服务。公司每天处理超过4000亿条金融数据，峰值时每秒处理1000万条消息。</li><li><strong>存储工程团队</strong>: Bloomberg 的存储工程团队负责设计和维护公司的存储产品，支持文件存储、块存储和对象存储，专注于软件定义存储（SDS）技术，特别是 Ceph 支持的块存储和对象存储。</li><li><strong>会议目标</strong>: 讨论 Ceph RGW（RADOS Gateway）对象存储中的数据一致性问题，并提出解决方案。</li></ul><h4 id="_2-ceph-rgw-集群概述" tabindex="-1">2. <strong>Ceph RGW 集群概述</strong> <a class="header-anchor" href="#_2-ceph-rgw-集群概述" aria-label="Permalink to &quot;2. **Ceph RGW 集群概述**&quot;">​</a></h4><ul><li><strong>集群规模</strong>: Bloomberg 拥有多个 Ceph 集群，分布在四个数据中心，包含数千个 OSD（Object Storage Daemon）和数百万个桶。</li><li><strong>架构</strong>: 每个集群由两个数据中心组成，采用多站点（multisite）设置，RGW 数据在数据中心之间同步复制。</li><li><strong>数据布局</strong>: RGW 数据分散在多个池中，包括元数据池、索引池、数据池等，数据一致性主要集中在桶和对象的元数据及索引上。</li></ul><h4 id="_3-数据一致性问题" tabindex="-1">3. <strong>数据一致性问题</strong> <a class="header-anchor" href="#_3-数据一致性问题" aria-label="Permalink to &quot;3. **数据一致性问题**&quot;">​</a></h4><ul><li><strong>主要原因</strong>: 数据分散在多个位置，大多数操作是异步的，部分操作不是原子的，导致竞态条件。此外，RGW 实例崩溃可能导致内存中的数据丢失。</li><li><strong>多站点复制问题</strong>: 在多站点设置中，特别是主动-主动（active-active）模式下，数据一致性问题更加复杂。</li><li><strong>后果</strong>: 数据不一致可能导致错误的 S3 请求响应、数据丢失、存储空间浪费等问题。</li></ul><h4 id="_4-实际案例分析" tabindex="-1">4. <strong>实际案例分析</strong> <a class="header-anchor" href="#_4-实际案例分析" aria-label="Permalink to &quot;4. **实际案例分析**&quot;">​</a></h4><ul><li><strong>案例1: 多部分上传（Multipart Upload）问题</strong>- 客户端报告存储空间超限，但实际数据量远小于分配的配额。原因是多部分上传过程中，部分中间对象未被正确清理。</li><li><strong>案例2: 版本更新竞态条件</strong>- 在多站点设置中，对象版本在不同站点之间不一致，导致数据丢失。</li><li><strong>案例3: RGW 崩溃一致性问题</strong>- RGW 实例崩溃导致部分数据未写入日志，进而导致数据丢失。</li><li><strong>其他案例</strong>: 索引与数据不一致、生命周期（LC）分片不一致、桶重分片（Resharding）问题等。</li></ul><h4 id="_5-解决方案-桶清理-bucket-scrubbing" tabindex="-1">5. <strong>解决方案：桶清理（Bucket Scrubbing）</strong> <a class="header-anchor" href="#_5-解决方案-桶清理-bucket-scrubbing" aria-label="Permalink to &quot;5. **解决方案：桶清理（Bucket Scrubbing）**&quot;">​</a></h4><ul><li><strong>目标</strong>: 主动检测和修复数据不一致问题，类似于 PG（Placement Group）清理，但针对 S3 数据进行桶级别的清理。</li><li><strong>系统要求</strong>: 支持后台运行，不影响客户端流量，支持扩展模块，支持报告模式和自动修复模式。</li><li><strong>架构设计</strong>: 使用桶清理分片记录桶列表及清理状态，多个清理处理器并行运行，每个处理器处理不同类型的数据一致性检查。</li><li><strong>未来计划</strong>: 与社区讨论设计方案，构建框架并开发原型模块。</li></ul><h4 id="_6-问答环节" tabindex="-1">6. <strong>问答环节</strong> <a class="header-anchor" href="#_6-问答环节" aria-label="Permalink to &quot;6. **问答环节**&quot;">​</a></h4><ul><li><strong>问题1</strong>: 是否所有的数据一致性检查都需要了解 Ceph 内部机制？ <ul><li><strong>回答</strong>: 数据一致性检查主要由 RGW 完成，类似于生命周期处理，但作为后台任务独立运行。</li></ul></li><li><strong>问题2</strong>: 是否考虑将数据一致性检查模块化？ <ul><li><strong>回答</strong>: 是的，模块化设计可以更细粒度地处理不同类型的数据不一致问题，便于开发人员参与。</li></ul></li><li><strong>问题3</strong>: 数据一致性检查是否会影响其他系统组件？ <ul><li><strong>回答</strong>: 通过配置工作负载，可以控制对客户端流量的影响。修复数据不一致时，可能会对系统其他部分产生影响，因此需要逐案分析。</li></ul></li></ul><p><strong>总结</strong>: 本次会议讨论了 Ceph RGW 对象存储中的数据一致性问题，分析了多个实际案例，并提出了基于桶清理的解决方案。未来计划包括与社区合作，开发和测试相关模块，确保 Ceph RGW 数据的一致性和可靠性。</p>',17)])])}const c=e(s,[["render",a]]);export{p as __pageData,c as default};
